    mass = 5;
    g = 9.81;
    gravitational_energy = mass * g * (end_pos(3) / 1000); % J

    % 若 joint_avg_speed 是 rad/s，这里按转动动能计算。
    rotational_energy = 0.5 * sum(joint_inertia .* joint_avg_speed.^2);

    f(2) = rotational_energy + gravitational_energy;
end

function [c, ceq] = constraint_function(theta)
    global target_pos;
    [end_pos, ~] = forward_kinematics(theta);

