% 定义全局变量
global DH_params target_pos joint_inertia joint_avg_speed;

% 设置DH参数 [a, alpha, d, theta_min, theta_max]
DH_params = [
    300, -90, 600, -160, 160;
    1200, 0,   0, -150,  15;
    300, -90,  0, -200,  80;
    0,   -90, 1200, -180, 180;
    0,   -90,  0, -120, 120;
